-- Sandbox audits (flat — run all three here)
SELECT e.id FROM enrollments e LEFT JOIN developers d ON d.id = e.developer_id WHERE d.id IS NULL;
SELECT e.id FROM enrollments e LEFT JOIN courses c ON c.id = e.course_id WHERE c.id IS NULL;
SELECT developer_id, course_id, COUNT(*) AS n FROM enrollments GROUP BY developer_id, course_id HAVING COUNT(*) > 1;

